execution_reports <- function(con,directory='docs') {
  dir.create(directory,recursive=TRUE,showWarnings=FALSE)
  # Source inventory is an availability denominator, not proof of a full season.
  report<-DBI::dbGetQuery(con,"WITH years AS (SELECT season FROM historical_games UNION SELECT season FROM schedule_inventory), i AS (SELECT season,count(*) source_schedule_games,count(*) FILTER(WHERE has_pbp) raw_sdv_pbp_games,count(*) FILTER(WHERE validation_status='quarantined') quarantined_games FROM schedule_inventory GROUP BY season), g AS (SELECT season,count(*) canonical_games FROM games GROUP BY season), p AS (SELECT g.season,count(*) possession_rows,count(DISTINCT p.game_id) possession_games FROM possessions p JOIN games g USING(game_id) GROUP BY g.season), l AS (SELECT g.season,count(*) lineup_rows,count(DISTINCT l.game_id) lineup_games FROM lineups l JOIN games g USING(game_id) GROUP BY g.season), e AS (SELECT g.season,count(*) event_rows,count(DISTINCT e.game_id) admitted_pbp_games FROM pbp_events e JOIN games g USING(game_id) GROUP BY g.season), s AS (SELECT g.season,count(*) shot_rows,count(*) FILTER(WHERE x IS NOT NULL AND y IS NOT NULL) coordinate_rows,count(*) FILTER(WHERE observation_type LIKE 'reconstructed%') reconstructed_shot_values FROM shot_attempts s JOIN games g USING(game_id) GROUP BY g.season), h AS (SELECT season,count(*) nba_source_games FROM historical_games GROUP BY season), r AS (SELECT season,count(*) FILTER(WHERE possessions_status='reconciled' AND lineups_status='reconciled') both_reconstructions_games,count(*) FILTER(WHERE possessions_status!='reconciled' OR lineups_status!='reconciled') reconstruction_unresolved_games FROM reconstruction_status GROUP BY season), recovered AS (SELECT season,count(*) nba_recovered_box_games FROM sdv_history_status WHERE box_status='reconstructed' GROUP BY season), checks AS (SELECT c.game_id,bool_and(c.passed IS TRUE) agrees,bool_and(c.independent IS TRUE) independent,count(*) n FROM reconciliation_checks c GROUP BY c.game_id), checked AS (SELECT g.season,count(*) FILTER(WHERE agrees AND n=20) reference_agree_games,count(*) FILTER(WHERE agrees AND independent AND n=20) independent_reference_agree_games,count(*) FILTER(WHERE agrees AND independent AND n=20 AND r.possessions_status='reconciled' AND r.lineups_status='reconciled') fully_reconciled_games FROM checks JOIN games g USING(game_id) LEFT JOIN reconstruction_status r USING(game_id) GROUP BY g.season) SELECT years.season,CAST(NULL AS INTEGER) expected_league_games,'unestablished complete independent schedule' expected_status,coalesce(i.source_schedule_games,0) source_schedule_games,coalesce(h.nba_source_games,0) nba_source_games,coalesce(g.canonical_games,0) canonical_games,coalesce(i.quarantined_games,0) quarantined_games,coalesce(i.raw_sdv_pbp_games,0) raw_sdv_pbp_games,coalesce(e.admitted_pbp_games,0) admitted_pbp_games,coalesce(e.event_rows,0) event_rows,coalesce(s.shot_rows,0) shot_rows,coalesce(s.coordinate_rows,0) coordinate_rows,coalesce(s.reconstructed_shot_values,0) reconstructed_shot_values,coalesce(p.possession_games,0) possession_games,coalesce(p.possession_rows,0) possession_rows,coalesce(l.lineup_games,0) lineup_games,coalesce(l.lineup_rows,0) lineup_rows,coalesce(r.both_reconstructions_games,0) both_reconstructions_games,coalesce(r.reconstruction_unresolved_games,0) reconstruction_unresolved_games,coalesce(recovered.nba_recovered_box_games,0) nba_recovered_box_games,coalesce(checked.reference_agree_games,0) reference_agree_games,coalesce(checked.independent_reference_agree_games,0) independent_reference_agree_games,coalesce(checked.fully_reconciled_games,0) fully_reconciled_games FROM years LEFT JOIN i USING(season) LEFT JOIN h USING(season) LEFT JOIN g USING(season) LEFT JOIN p USING(season) LEFT JOIN l USING(season) LEFT JOIN e USING(season) LEFT JOIN s USING(season) LEFT JOIN r USING(season) LEFT JOIN recovered USING(season) LEFT JOIN checked USING(season) ORDER BY season")
  for(kind in c('team','player')) {
    a<-DBI::dbGetQuery(con,paste0('SELECT g.season,count(DISTINCT b.game_id) box_games,count(*) box_rows FROM ',kind,'_box_scores b JOIN games g USING(game_id) GROUP BY g.season'))
    report[[paste0('validated_',kind,'_box_games')]]<-ifelse(is.na(match(report$season,a$season)),0,a$box_games[match(report$season,a$season)])
    report[[paste0('validated_',kind,'_box_rows')]]<-ifelse(is.na(match(report$season,a$season)),0,a$box_rows[match(report$season,a$season)])
  }
  report$observed_tracking_rows<-0L;report$provider_estimated_tracking_rows<-0L
  if(DBI::dbExistsTable(con,'tracking_provider_context')) {
    t<-DBI::dbGetQuery(con,"SELECT season,count(*) n FROM tracking_provider_context WHERE validation_status='estimated' GROUP BY season")
    report$provider_estimated_tracking_rows<-ifelse(is.na(match(report$season,t$season)),0,t$n[match(report$season,t$season)])
  }
  utils::write.csv(report,file.path(directory,'execution_season_completeness.csv'),row.names=FALSE,na='')
  compact<-report[c('season','source_schedule_games','canonical_games','admitted_pbp_games','shot_rows','possession_games','lineup_games','fully_reconciled_games','quarantined_games')]
  writeLines(c('# Historical execution coverage','',paste('Generated:',format(Sys.time(),tz='UTC',usetz=TRUE)),paste('Physical method:',reconstruction_version),'',
    'Schedule counts are the eligible records in the pinned SDV archive. Complete independent league denominators remain unestablished. NBA source games are a separate observation namespace and cannot be added to canonical counts. Games with valid boxes survive missing or invalid PBP. Fully reconciled means both physical reconstructions and all 20 distinct-provider game-total comparisons pass. NBA-recovered boxes compared to NBA totals are dependent and excluded from that column. Distinct providers can still share upstream errors. Zero is no admitted data, not proof that the historical activity never occurred. Raw observations and failures remain local.',
    '',knitr::kable(compact,format='pipe',row.names=FALSE),'',
    'See execution_season_completeness.csv for counts by family and reconstruction rows, historical_completeness.csv for the separate NBA observation layer, historical_unresolved_games.csv for historical game-level exceptions, unresolved_games.csv for the modern cohort, and execution_reconciliation.csv for current metric-level results.'),file.path(directory,'execution_season_completeness.md'))
  rec<-DBI::dbGetQuery(con,"SELECT g.season,c.metric,c.independent,CASE WHEN c.passed IS TRUE THEN 'match' WHEN c.passed IS FALSE THEN 'mismatch' ELSE 'unavailable' END status,count(*) checks FROM reconciliation_checks c JOIN games g USING(game_id) GROUP BY g.season,c.metric,c.independent,status ORDER BY g.season,c.metric,c.independent,status")
  utils::write.csv(rec,file.path(directory,'execution_reconciliation.csv'),row.names=FALSE)
  lb<-DBI::dbGetQuery(con,"WITH b AS (SELECT season,count(DISTINCT game_id) nba_box_games FROM historical_player_boxes WHERE player_id='nba:2544' GROUP BY season), c AS (SELECT g.season,count(DISTINCT p.game_id) canonical_box_games,count(DISTINCT p.game_id) FILTER(WHERE s.possessions_status='reconciled') possession_games,count(DISTINCT p.game_id) FILTER(WHERE s.lineups_status='reconciled') lineup_games FROM player_box_scores p JOIN games g USING(game_id) LEFT JOIN reconstruction_status s USING(game_id) WHERE p.player_id='espn:1966' GROUP BY g.season) SELECT b.season,b.nba_box_games,coalesce(c.canonical_box_games,0) canonical_box_games,coalesce(c.possession_games,0) possession_games,coalesce(c.lineup_games,0) lineup_games,'observed source counts; complete career denominators not certified' limitation FROM b LEFT JOIN c USING(season) ORDER BY b.season")
  utils::write.csv(lb,file.path(directory,'lebron_career_coverage.csv'),row.names=FALSE)
  matrix<-do.call(rbind,lapply(c('canonical_games','validated_team_box_games','validated_player_box_games','admitted_pbp_games','shot_rows','possession_games','lineup_games','provider_estimated_tracking_rows'),function(k) {
    z<-report$season[report[[k]]>0];data.frame(family=k,earliest=if(length(z))min(z) else NA_character_,latest=if(length(z))max(z) else NA_character_,status=if(k=='provider_estimated_tracking_rows')'estimated' else if(k%in%c('possession_games','lineup_games'))'reconstructed' else 'observed_or_checked',limitation='nonzero admitted records; not complete seasons')
  }))
  utils::write.csv(matrix,file.path(directory,'execution_availability_matrix.csv'),row.names=FALSE,na='')
  invisible(report)
}

execution_integrity <- function(con) {
  sql<-c(
    sdv_status_game_admission="SELECT count(*) FROM sdv_history_status s LEFT JOIN games g USING(game_id) WHERE (s.box_status IN ('observed','reconstructed') AND g.game_id IS NULL) OR (s.box_status='failed_validation' AND g.game_id IS NOT NULL)",
    sdv_status_season="SELECT count(*) FROM sdv_history_status s JOIN games g USING(game_id) WHERE s.season!=g.season",
    sdv_calendar_bounds="SELECT count(*) FROM games g JOIN sdv_history_status s USING(game_id) WHERE g.game_date<CAST(substr(g.season,1,4)||'-07-01' AS DATE) OR g.game_date>CAST(CAST(CAST(substr(g.season,1,4) AS INTEGER)+1 AS VARCHAR)||'-06-30' AS DATE)",
    historical_source_partition_count='SELECT abs(count(*)-22) FROM sdv_history_checkpoints',
    recovery_unique_nba_identity='SELECT count(*) FROM (SELECT nba_player_id FROM sdv_nba_player_links GROUP BY nba_player_id HAVING count(DISTINCT player_id)>1)',
    recovery_unique_espn_identity='SELECT count(*) FROM (SELECT player_id FROM sdv_nba_player_links GROUP BY player_id HAVING count(DISTINCT nba_player_id)>1)',
    recovery_links_have_games='SELECT count(*) FROM sdv_nba_player_links l LEFT JOIN games g USING(game_id) WHERE g.game_id IS NULL',
    recovered_box_source="SELECT count(*) FROM sdv_history_status s JOIN team_box_scores b USING(game_id) JOIN datasets d USING(dataset_id) WHERE s.box_status='reconstructed' AND d.source_id!='eoin_moore_nba'",
    no_defender_assignments='SELECT count(*) FROM matchup_observations')
  if(DBI::dbExistsTable(con,'tracking_provider_context'))sql<-c(sql,
    tracking_row_pointer='SELECT count(*) FROM tracking_provider_context WHERE source_row<1 OR dataset_id IS NULL',
    tracking_duplicate_records='SELECT count(*) FROM (SELECT dataset_id,source_row FROM tracking_provider_context GROUP BY dataset_id,source_row HAVING count(*)!=1)',
    tracking_duplicate_metrics='SELECT count(*) FROM (SELECT dataset_id,source_row,metric FROM tracking_provider_estimates GROUP BY dataset_id,source_row,metric HAVING count(*)!=1)',
    tracking_metric_context='SELECT count(*) FROM tracking_provider_estimates e LEFT JOIN tracking_provider_context c USING(dataset_id,source_row) WHERE c.source_row IS NULL',
    tracking_estimate_semantics="SELECT count(*) FROM tracking_provider_estimates WHERE (status='estimated' AND (value IS NULL OR NOT isfinite(value))) OR (status!='estimated' AND value IS NOT NULL) OR status NOT IN ('estimated','source_missing','failed_validation')",
    tracking_uncertainty_missing="SELECT count(*) FROM tracking_provider_estimates WHERE uncertainty IS NOT NULL OR uncertainty_status!='source_missing'")
  z<-data.frame(check=names(sql),violations=vapply(sql,function(q)as.numeric(DBI::dbGetQuery(con,q)[[1]][1]),numeric(1)))
  paths<-DBI::dbGetQuery(con,"SELECT d.raw_path FROM sdv_history_checkpoints c JOIN datasets d ON d.dataset_id='sdv-history:player_box_scores:'||c.season||':'||c.signature")$raw_path
  if(length(paths)) {
    files<-paste(DBI::dbQuoteString(con,normalizePath(paths,winslash='/')),collapse=',')
    evidence<-paste(paste0('coalesce(p.',c('minutes','points','fgm','fga','fg3m','fg3a','ftm','fta','assists','turnovers','rebounds'),',0)>0'),collapse=' OR ')
    q<-paste0("SELECT count(*) FROM read_parquet([",files,"],union_by_name=TRUE) p JOIN sdv_history_status s USING(game_id) LEFT JOIN player_box_scores c ON p.game_id=c.game_id AND p.player_id=c.player_id WHERE s.box_status='reconstructed' AND c.player_id IS NULL AND (",evidence,')')
    z<-rbind(z,data.frame(check='recovery_unmatched_playing_evidence',violations=as.numeric(DBI::dbGetQuery(con,q)[[1]][1])))
  }
  z$passed<-z$violations==0;z
}
